    ck_tile::tuple<ck_tile::sequence<1, 1>,
                   ck_tile::sequence<2, 2>>,       // P -> RH minor
    ck_tile::sequence<1, 1, 2, 2>,                // Y -> RH major
    ck_tile::sequence<0, 3, 0, 3>                 // Y -> RH minor
