    ck_tile::address_space_enum::global>(ptr, ck_tile::make_tuple(M, N));

// 3. create tile window loaddata
auto window = ck_tile::make_tile_window(
    tensor_view, window_lengths, origin, distribution);
auto tile_data = window.load();

